"use client";
import React, { useState, useEffect } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import Link from "next/link";
import { Phone, Lock, Eye, EyeOff, ArrowLeft, CheckCircle, RefreshCw, User } from "lucide-react";
import { lookupReservation } from "@/features/hotel-booking/api/booking-api";
import { formatVND } from "@/features/hotel-booking/utils/search-helpers";

// ================================================================
// Lumina Guest Portal — Login bằng Mã đặt phòng + Số điện thoại
// (Khách không có tài khoản — chỉ cần mã + SĐT để xem lịch sử đặt phòng)
// ================================================================

type Tab = "lookup" | "found";

export default function LoginPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const redirectTo = searchParams.get("redirect") ?? "/account";

  const [tab, setTab] = useState<Tab>("lookup");
  const [code, setCode] = useState("");
  const [phone, setPhone] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reservationData, setReservationData] = useState<{
    code: string;
    guestName: string;
    status: string;
    checkIn: string;
    checkOut: string;
    nights: number;
    estimatedTotal: number;
    rooms: { roomNumber: string; roomTypeName: string; adults: number; children: number; pricePerNight: number }[];
  } | null>(null);

  async function handleLookup(e: React.FormEvent) {
    e.preventDefault();
    if (!code.trim() || !phone.trim()) return;
    setIsLoading(true);
    setError(null);
    try {
      const data = await lookupReservation(code.trim().toUpperCase(), phone.trim());
      setReservationData({
        code: data.code,
        guestName: data.guestName,
        status: data.status,
        checkIn: data.checkIn,
        checkOut: data.checkOut,
        nights: data.nights,
        estimatedTotal: data.estimatedTotal,
        rooms: data.rooms,
      });
      setTab("found");
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Không tìm thấy đơn đặt phòng.");
    } finally {
      setIsLoading(false);
    }
  }

  const statusMap: Record<string, { label: string; color: string }> = {
    Draft: { label: "Chờ xác nhận", color: "text-amber-600 bg-amber-50 border-amber-200" },
    Confirmed: { label: "Đã xác nhận", color: "text-emerald-600 bg-emerald-50 border-emerald-200" },
    CheckedIn: { label: "Đang lưu trú", color: "text-blue-600 bg-blue-50 border-blue-200" },
    CheckedOut: { label: "Đã trả phòng", color: "text-gray-600 bg-gray-50 border-gray-200" },
    Cancelled: { label: "Đã hủy", color: "text-red-600 bg-red-50 border-red-200" },
    NoShow: { label: "Không đến", color: "text-red-600 bg-red-50 border-red-200" },
  };

  return (
    <div className="min-h-screen bg-linear-to-br from-[#0194f3] via-[#0177c8] to-[#015fa0] flex items-center justify-center px-4 py-12">
      {/* Background decoration */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute -top-32 -right-32 w-96 h-96 bg-white/5 rounded-full" />
        <div className="absolute -bottom-24 -left-24 w-72 h-72 bg-white/5 rounded-full" />
        <div className="absolute top-1/3 left-1/4 w-48 h-48 bg-white/5 rounded-full" />
      </div>

      <div className="w-full max-w-md relative">
        {/* Logo */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center gap-2 mb-3">
            <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center shadow-lg">
              <svg viewBox="0 0 24 24" width="22" height="22" fill="#0194f3"><path d="M7 13c1.66 0 3-1.34 3-3S8.66 7 7 7s-3 1.34-3 3 1.34 3 3 3zm12-6h-8v7H3V5H1v15h2v-3h18v3h2v-9c0-2.21-1.79-4-4-4z"/></svg>
            </div>
            <span className="text-white font-bold text-2xl tracking-tight">lumina</span>
          </div>
          <p className="text-white/80 text-sm">Tra cứu đặt phòng của bạn</p>
        </div>

        {/* Card */}
        <div className="bg-white rounded-3xl shadow-[0_20px_60px_rgba(0,0,0,0.3)] overflow-hidden">
          {tab === "lookup" ? (
            <div className="p-8">
              <h1 className="text-[22px] font-bold text-[#03121a] mb-1">Tra cứu đặt phòng</h1>
              <p className="text-[13px] text-[#687176] mb-6">
                Nhập mã đặt phòng và số điện thoại để xem thông tin chuyến đi của bạn.
              </p>

              <form onSubmit={handleLookup} className="space-y-4">
                <div>
                  <label className="block text-[13px] font-bold text-[#03121a] mb-1.5">
                    Mã đặt phòng
                  </label>
                  <div className="relative">
                    <CheckCircle size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#687176]" />
                    <input
                      required value={code} onChange={e => setCode(e.target.value.toUpperCase())}
                      placeholder="RSV-260928-0001"
                      className="w-full pl-9 pr-4 py-3 text-[14px] border border-gray-300 rounded-xl focus:border-[#0194f3] focus:ring-1 focus:ring-[#0194f3] outline-none font-mono tracking-wider uppercase"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-[13px] font-bold text-[#03121a] mb-1.5">
                    Số điện thoại đặt phòng
                  </label>
                  <div className="relative">
                    <Phone size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#687176]" />
                    <input
                      required value={phone} onChange={e => setPhone(e.target.value)}
                      placeholder="0912 345 678" type="tel"
                      className="w-full pl-9 pr-4 py-3 text-[14px] border border-gray-300 rounded-xl focus:border-[#0194f3] focus:ring-1 focus:ring-[#0194f3] outline-none"
                    />
                  </div>
                </div>

                {error && (
                  <div className="bg-red-50 border border-red-200 rounded-xl p-3 text-[13px] text-red-600">
                    ⚠️ {error}
                  </div>
                )}

                <button
                  type="submit" disabled={isLoading}
                  className="w-full bg-[#0194f3] hover:bg-[#007ce8] disabled:bg-gray-300 text-white font-bold py-3.5 rounded-xl transition-all flex items-center justify-center gap-2 text-[15px]"
                >
                  {isLoading ? <><RefreshCw size={16} className="animate-spin" /> Đang tra cứu...</> : "Tra cứu đặt phòng"}
                </button>
              </form>

              <div className="mt-6 pt-6 border-t border-gray-100 text-center">
                <p className="text-[13px] text-[#687176]">
                  Chưa có đặt phòng?{" "}
                  <Link href="/search" className="text-[#0194f3] font-bold hover:underline">
                    Đặt phòng ngay
                  </Link>
                </p>
              </div>

              {/* Tip */}
              <div className="mt-4 bg-[#f2f9ff] rounded-xl p-3 flex gap-2 items-start">
                <span className="text-[18px]">💡</span>
                <p className="text-[12px] text-[#687176]">
                  Mã đặt phòng được gửi qua tin nhắn sau khi đặt thành công, định dạng <strong>RSV-yyMMdd-####</strong>.
                </p>
              </div>
            </div>
          ) : (
            /* Found result */
            <div className="p-8">
              <button onClick={() => { setTab("lookup"); setReservationData(null); }}
                className="flex items-center gap-1.5 text-[13px] text-[#687176] hover:text-[#0194f3] mb-5 transition-colors">
                <ArrowLeft size={14} /> Tra cứu lại
              </button>

              <div className="flex items-center gap-3 mb-5">
                <div className="w-12 h-12 bg-emerald-50 rounded-2xl flex items-center justify-center">
                  <CheckCircle size={24} className="text-emerald-500" />
                </div>
                <div>
                  <p className="font-bold text-[#03121a] text-[17px]">Tìm thấy đặt phòng!</p>
                  <p className="text-[13px] text-[#687176]">Xin chào, {reservationData?.guestName}</p>
                </div>
              </div>

              {reservationData && (
                <div className="space-y-3">
                  <div className="bg-[#f7f9fa] rounded-2xl p-4 space-y-2.5">
                    <div className="flex items-center justify-between">
                      <span className="text-[13px] text-[#687176]">Mã đặt phòng</span>
                      <span className="font-bold text-[#0194f3] font-mono">{reservationData.code}</span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-[13px] text-[#687176]">Trạng thái</span>
                      <span className={`text-[12px] font-bold px-2.5 py-0.5 rounded-full border ${statusMap[reservationData.status]?.color ?? "text-gray-600 bg-gray-50 border-gray-200"}`}>
                        {statusMap[reservationData.status]?.label ?? reservationData.status}
                      </span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-[13px] text-[#687176]">Nhận phòng</span>
                      <span className="font-semibold text-[#03121a] text-[13px]">
                        {new Date(reservationData.checkIn).toLocaleDateString("vi-VN", { weekday: "short", day: "2-digit", month: "short", year: "numeric" })}
                      </span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-[13px] text-[#687176]">Trả phòng</span>
                      <span className="font-semibold text-[#03121a] text-[13px]">
                        {new Date(reservationData.checkOut).toLocaleDateString("vi-VN", { weekday: "short", day: "2-digit", month: "short", year: "numeric" })}
                      </span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-[13px] text-[#687176]">Số đêm</span>
                      <span className="font-semibold text-[#03121a] text-[13px]">{reservationData.nights} đêm</span>
                    </div>
                    {reservationData.rooms.map((r, i) => (
                      <div key={i} className="flex items-center justify-between border-t border-gray-200 pt-2">
                        <span className="text-[13px] text-[#687176]">Phòng {r.roomNumber}</span>
                        <span className="font-semibold text-[#03121a] text-[13px]">{r.roomTypeName}</span>
                      </div>
                    ))}
                    <div className="flex items-center justify-between border-t border-gray-200 pt-2">
                      <span className="text-[13px] font-bold text-[#03121a]">Tổng dự kiến</span>
                      <span className="font-bold text-[#ff5e1f] text-[17px]">{formatVND(reservationData.estimatedTotal)} đ</span>
                    </div>
                  </div>

                  <p className="text-[12px] text-[#687176] text-center">
                    📞 Liên hệ khách sạn: <strong>024 0123 4567</strong> để biết thêm thông tin
                  </p>

                  <button onClick={() => router.push("/search")}
                    className="w-full bg-[#0194f3] text-white font-bold py-3 rounded-xl hover:bg-[#007ce8] transition-colors text-[14px]">
                    Đặt thêm phòng
                  </button>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Footer */}
        <p className="text-center text-white/60 text-[12px] mt-6">
          © 2026 Lumina Boutique Hotel. Mọi quyền được bảo lưu.
        </p>
      </div>
    </div>
  );
}
